import{_ as n,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const k=JSON.parse('{"title":"Tổng cương Nghị định thư Khảo cổ","description":"","frontmatter":{},"headers":[],"relativePath":"vi/84-考古协议总纲.md","filePath":"vi/84-考古协议总纲.md","lastUpdated":null}'),a={name:"vi/84-考古协议总纲.md"};function o(g,h,u,l,r,p){return t(),c("div",null,[...h[0]||(h[0]=[i('<h1 id="tong-cuong-nghi-đinh-thu-khao-co" tabindex="-1">Tổng cương Nghị định thư Khảo cổ <a class="header-anchor" href="#tong-cuong-nghi-đinh-thu-khao-co" aria-label="Permalink to &quot;Tổng cương Nghị định thư Khảo cổ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>84</td></tr><tr><td>Mô-đun</td><td>Tương tác Liên mặt phẳng và Quy tắc Thời gian</td></tr><tr><td>Từ khóa cốt lõi</td><td>Nghị định thư khảo cổ, gương sao chép, không gian cách ly, chỉ truyền lại kiến thức, ô nhiễm thấp</td></tr></tbody></table><h2 id="_1-vi-tri-va-muc-tieu-cua-nghi-đinh-thu-khao-co" tabindex="-1">1. Vị trí và Mục tiêu của Nghị định thư Khảo cổ <a class="header-anchor" href="#_1-vi-tri-va-muc-tieu-cua-nghi-đinh-thu-khao-co" aria-label="Permalink to &quot;1. Vị trí và Mục tiêu của Nghị định thư Khảo cổ&quot;">​</a></h2><p>Khảo cổ liên mặt phẳng và khảo cổ lùi lại thời gian là những phương tiện quan trọng để văn minh cộng sinh neo thu nhận kiến thức lịch sử và hiểu được sự tiến hóa của vũ trụ. Tuy nhiên, bản thân hành động khảo cổ có rủi ro cao — việc trực tiếp xâm nhập vào mặt phẳng mục tiêu hoặc giai đoạn mục tiêu để thực hiện khai quật khảo cổ có thể gây ra tổn thất vật lý, xáo trộn luật pháp và ô nhiễm văn hóa cho đối tượng mục tiêu. Để quy phạm hành động khảo cổ và giảm thiểu rủi ro khảo cổ, Hengyuanzhou đã ban hành &quot;Tổng cương Nghị định thư Khảo cổ&quot; thống nhất, làm quy phạm hoạt động cơ bản cho tất cả các hoạt động khảo cổ liên mặt phẳng và lùi lại thời gian.</p><p>Mục tiêu cốt lõi của nghị định thư khảo cổ có thể được tóm tắt trong &quot;ba mức tối đa&quot;: tối đa hóa việc thu nhận kiến thức lịch sử hoàn chỉnh, tối thiểu hóa sự can thiệp và tổn thất đối với đối tượng mục tiêu, tối đa hóa việc đảm bảo an toàn cho nhân sự khảo cổ. Có một sự căng thẳng nội tại giữa ba mục tiêu này — sự hoàn chỉnh của việc thu nhận kiến thức thường đòi hỏi sự tiếp xúc sâu hơn, trong khi nguyên tắc can thiệp thấp lại hạn chế độ sâu của sự tiếp xúc. Toàn bộ thiết kế thể chế của nghị định thư khảo cổ đều nhằm tìm ra sự cân bằng tối ưu giữa ba yếu tố này.</p><p>Nghị định thư khảo cổ áp dụng cho các kịch bản sau: điều tra khảo cổ đối với di tích văn minh ở mặt phẳng chưa biết, phục hồi lịch sử các nền văn minh đã tuyệt chủng thông qua lùi lại thời gian, khảo cổ sâu ở cấp độ luật pháp đối với di tích cổ của mặt phẳng自己, và khai quật cứu hộ đối với di tích cổ xưa trong mặt phẳng có luật pháp vỡ.</p><h2 id="_2-ba-yeu-to-cua-ke-hoach-khao-co" tabindex="-1">2. Ba Yếu tố của Kế hoạch Khảo cổ <a class="header-anchor" href="#_2-ba-yeu-to-cua-ke-hoach-khao-co" aria-label="Permalink to &quot;2. Ba Yếu tố của Kế hoạch Khảo cổ&quot;">​</a></h2><p>Kế hoạch khảo cổ tiêu chuẩn của Hengyuanzhou bao gồm ba yếu tố cốt lõi, được gọi là &quot;ba yếu tố khảo cổ&quot;:</p><h3 id="_2-1-guong-sao-chep" tabindex="-1">2.1 Gương Sao chép <a class="header-anchor" href="#_2-1-guong-sao-chep" aria-label="Permalink to &quot;2.1 Gương Sao chép&quot;">​</a></h3><p>Gương sao chép là một thiết bị sao chép độ chính xác cao dựa trên luật pháp không gian, có thể thực hiện sao chép hoàn chỉnh 1:1 cấu trúc vật chất, năng lượng và thông tin trong khu vực mục tiêu mà không cần tiếp xúc với vật thể gốc. Nguyên lý hoạt động của gương sao chép là quét tất cả trạng thái hạt và phân bố trường năng lượng của khu vực mục tiêu thông qua luật pháp không gian, sau đó xây dựng lại một bản sao hoàn toàn giống hệt trong không gian cách ly. Quá trình sao chép không thay đổi bất kỳ trạng thái nào của vật thể gốc, do đó không gây ra bất kỳ can thiệp vật lý nào vào địa điểm khảo cổ.</p><p>Độ chính xác sao chép của gương sao chép đạt đến cấp độ hạ nguyên tử, có thể khôi phục hoàn toàn cấu trúc vật chất, dư lượng năng lượng, dấu ấn ý thức, thậm chí các mảnh chuỗi nhân quả trong khu vực mục tiêu. Phạm vi sao chép có thể được điều chỉnh theo nhu cầu khảo cổ, đơn vị sao chép nhỏ nhất là một hiện vật đơn lẻ, lớn nhất có thể bao phủ toàn bộ cụm di tích. Thời gian sao chép phụ thuộc vào kích thước của phạm vi sao chép, sao chép một hiện vật đơn lẻ thường hoàn thành trong vài phút, sao chép cụm di tích lớn có thể mất vài ngày.</p><h3 id="_2-2-khong-gian-cach-ly" tabindex="-1">2.2 Không gian Cách ly <a class="header-anchor" href="#_2-2-khong-gian-cach-ly" aria-label="Permalink to &quot;2.2 Không gian Cách ly&quot;">​</a></h3><p>Không gian cách ly là một vùng luật pháp độc lập được xây dựng thông qua công nghệ điều phối luật pháp không gian, dùng để chứa các bản sao khảo cổ do gương sao chép tạo ra, và làm nơi làm việc cho nhân sự khảo cổ. Không gian cách ly và mặt phẳng mục tiêu hoặc giai đoạn mục tiêu được ngăn cách bởi một rào cản luật pháp hoàn chỉnh, đảm bảo rằng các hoạt động khảo cổ không gây ra bất kỳ tác động ngược nào đối với mục tiêu ban đầu.</p><p>Các tham số luật pháp bên trong không gian cách ly có thể được tùy chỉnh theo nhu cầu khảo cổ, bao gồm: mô phỏng các tham số môi trường của mặt phẳng mục tiêu để đảm bảo sự ổn định của bản sao hiện vật, thiết lập trường luật pháp phân tích đặc biệt để hỗ trợ nghiên cứu khảo cổ, và xây dựng trường phòng ngừa ô nhiễm nghiêm ngặt để ngăn chặn rò rỉ năng lượng và ý thức của nhân sự khảo cổ. Kích thước của không gian cách ly có thể được mở rộng theo nhu cầu, lớn nhất có thể chứa toàn bộ bản sao di tích cấp thành phố.</p><h3 id="_2-3-chi-truyen-lai-kien-thuc" tabindex="-1">2.3 Chỉ Truyền lại Kiến thức <a class="header-anchor" href="#_2-3-chi-truyen-lai-kien-thuc" aria-label="Permalink to &quot;2.3 Chỉ Truyền lại Kiến thức&quot;">​</a></h3><p>&quot;Chỉ truyền lại kiến thức&quot; là một trong những nguyên tắc cốt lõi của nghị định thư khảo cổ, có nghĩa là những gì thu được từ đối tượng mục tiêu trong quá trình khảo cổ chỉ có thể là kiến thức và thông tin trừu tượng, không được truyền lại bất kỳ vật chất, năng lượng hoặc sinh vật sống nào. Sau khi nhân sự khảo cổ nghiên cứu bản sao trong không gian cách ly, chỉ có thể mang kết luận nghiên cứu, hồ sơ dữ liệu và báo cáo phân tích trở lại mặt phẳng自己 dưới dạng thông tin thuần túy; bản sao本身 và bất kỳ mẫu vật chất nào được trích xuất từ bản sao đều phải được phá hủy bên trong không gian cách ly.</p><p>Mục tiêu cơ bản của nguyên tắc này là ngăn chặn ô nhiễm liên mặt phẳng và xáo trộn dòng thời gian. Ngay cả một hạt bụi được trích xuất từ bản sao cũng có thể mang thông tin luật pháp của mặt phẳng mục tiêu, một khi xâm nhập vào mạng lưới luật pháp của mặt phẳng自己, có thể gây ra phản ứng chuỗi không thể dự đoán. Do đó, &quot;chỉ truyền lại kiến thức&quot; không phải là một đề xuất hoạt động có thể thương lượng, mà là một nguyên tắc cứng nhắc có hiệu lực pháp lý cưỡng chế.</p><h2 id="_3-quy-trinh-tieu-chuan-cua-hoat-đong-khao-co" tabindex="-1">3. Quy trình Tiêu chuẩn của Hoạt động Khảo cổ <a class="header-anchor" href="#_3-quy-trinh-tieu-chuan-cua-hoat-đong-khao-co" aria-label="Permalink to &quot;3. Quy trình Tiêu chuẩn của Hoạt động Khảo cổ&quot;">​</a></h2><p>Một hoạt động khảo cổ liên mặt phẳng hoặc lùi lại thời gian hoàn chỉnh tuân theo quy trình tiêu chuẩn sau:</p><table tabindex="0"><thead><tr><th>Giai đoạn</th><th>Nội dung Hoạt động</th><th>Bên chịu trách nhiệm</th><th>Tham chiếu Thời gian</th></tr></thead><tbody><tr><td>Giai đoạn 1: Phê duyệt Dự án</td><td>Nộp đơn xin khảo cổ, làm rõ mục tiêu, phạm vi và kế hoạch khảo cổ, xin giấy phép đi qua Cấp A hoặc giấy phép lùi lại</td><td>Đội khảo cổ → Cục Quản lý Mặt phẳng / Ủy ban Luật pháp Thời gian</td><td>7-30 ngày</td></tr><tr><td>Giai đoạn 2: Quan sát Trước</td><td>Theo hướng dẫn &quot;quan sát trước, sau đó can thiệp hạn chế&quot;, thực hiện quan sát thuần túy không dưới 72 giờ đối với khu vực mục tiêu</td><td>Đội khảo cổ</td><td>Hơn 72 giờ</td></tr><tr><td>Giai đoạn 3: Triển khai Gương Sao chép</td><td>Triển khai gương sao chép tại vị trí an toàn gần khu vực mục tiêu, đặt phạm vi sao chép và tham số độ chính xác</td><td>Đội kỹ thuật</td><td>Vài giờ đến vài ngày</td></tr><tr><td>Giai đoạn 4: Tạo Bản sao</td><td>Kích hoạt gương sao chép, sao chép hoàn chỉnh khu vực mục tiêu vào không gian cách ly đã được xây dựng trước</td><td>Đội kỹ thuật</td><td>Vài phút đến vài ngày</td></tr><tr><td>Giai đoạn 5: Khảo cổ trong Không gian Cách ly</td><td>Nhân sự khảo cổ xâm nhập vào không gian cách ly, thực hiện khai quật, phân tích và nghiên cứu có hệ thống đối với bản sao</td><td>Đội khảo cổ</td><td>Vài ngày đến vài năm</td></tr><tr><td>Giai đoạn 6: Tổ chức Kiến thức</td><td>Tổ chức kết quả khảo cổ, hình thành báo cáo nghiên cứu và cơ sở dữ liệu kiến thức, đảm bảo tất cả kết quả đều ở dạng thông tin thuần túy</td><td>Đội khảo cổ</td><td>Vài ngày đến vài tháng</td></tr><tr><td>Giai đoạn 7: Triển khai và Phá hủy</td><td>Nhân sự khảo cổ rút khỏi không gian cách ly, phá hủy tất cả vật chất bản sao và dư lượng năng lượng, đóng cửa không gian cách ly</td><td>Đội kỹ thuật + Đội giám sát</td><td>Vài giờ</td></tr><tr><td>Giai đoạn 8: Kiểm toán Sau</td><td>Nộp báo cáo khảo cổ hoàn chỉnh,接受 kiểm toán sau của Ủy ban Kiểm toán Luật pháp Thời gian hoặc Cục Quản lý Mặt phẳng</td><td>Ủy ban kiểm toán</td><td>Trong 30 ngày</td></tr></tbody></table><h2 id="_4-nang-luc-va-yeu-cau-đao-đuc-cua-nhan-su-khao-co" tabindex="-1">4. Năng lực và Yêu cầu Đạo đức của Nhân sự Khảo cổ <a class="header-anchor" href="#_4-nang-luc-va-yeu-cau-đao-đuc-cua-nhan-su-khao-co" aria-label="Permalink to &quot;4. Năng lực và Yêu cầu Đạo đức của Nhân sự Khảo cổ&quot;">​</a></h2><p>Nhân sự tham gia vào khảo cổ liên mặt phẳng và lùi lại thời gian phải có các năng lực sau: tu luyện giai đoạn ba trở lên của hệ thống điều phối luật pháp không gian, vượt qua chứng nhận năng lực của ủy ban đạo đức khảo cổ, hoàn thành không dưới 100 giờ đào tạo khảo cổ mô phỏng, và không có bất kỳ hồ sơ vi phạm luật pháp cộng sinh nào.</p><p>Nhân sự khảo cổ phải tuân thủ các yêu cầu đạo đức sau: tôn trọng văn hóa và tín ngưỡng của văn minh mục tiêu, không thực hiện phân biệt đối xử văn hóa hoặc đánh giá giá trị trong nghiên cứu; bảo vệ tính toàn vẹn của địa điểm khảo cổ, không phá hủy cấu trúc di tích để có được hiện vật; ghi chép và báo cáo trung thực các phát hiện khảo cổ, không làm giả hoặc che giấu dữ liệu khảo cổ; và tuân thủ nguyên tắc &quot;chỉ truyền lại kiến thức&quot;, không私自 mang bất kỳ mẫu vật chất nào ra khỏi không gian cách ly.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Tổng cương Nghị định thư Khảo cổ là cây cầu thể chế mà Hengyuanzhou xây dựng giữa việc khám phá kiến thức và bảo vệ văn minh. Với ba yếu tố — gương sao chép, không gian cách ly và chỉ truyền lại kiến thức — làm hỗ trợ kỹ thuật, quy trình tiêu chuẩn làm khuôn khổ hoạt động, và năng lực nhân sự cùng yêu cầu đạo đức làm đảm bảo nhân văn, nó xây dựng một mô hình khảo cổ &quot;ô nhiễm thấp, hiệu quả cao, có thể truy vết&quot;. Mô hình này đảm bảo rằng Hengyuanzhou, trong khi theo đuổi sự thật lịch sử, luôn duy trì sự tôn trọng cao nhất đối với các nền văn minh và thời đại khác.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>85-Kế hoạch Khảo cổ Xa xứ với Gương Sao chép</li><li>86-Quy trình Ô nhiễm Thấp trong Không gian Cách ly</li><li>87-Nguyên tắc Chỉ Truyền lại Kiến thức</li></ul>',27)])])}const m=n(a,[["render",o]]);export{k as __pageData,m as default};
